package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"testing"
)

func TestFuzzRouterPanic(t *testing.T) {
	segs := []string{"a", "b", "c", ":p", "*", "ab", ":q", "x"}
	rng := rand.New(rand.NewSource(1))
	paths := []string{"/", "/a", "/a/b", "/ab", "/a/b/c", "/x", "/a/x", "/a/b/c/d", "//", "/a//b", "", "/:", "/*", "/a/*", "/a/:p", "/a/:p/b", "/a/b/", "/ab/c"}
	for iter := 0; iter < 3000; iter++ {
		e := New()
		r := e.router
		n := 1 + rng.Intn(4)
		for i := 0; i < n; i++ {
			np := 1 + rng.Intn(4)
			p := ""
			for j := 0; j < np; j++ {
				p += "/" + segs[rng.Intn(len(segs))]
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						fmt.Printf("ADD PANIC route=%q: %v\n", p, rec)
					}
				}()
				r.Add(http.MethodGet, p, handlerFunc)
			}()
		}
		for _, p := range paths {
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						fmt.Printf("FIND PANIC path=%q routes=%v: %v\n", p, r.routes, rec)
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, p, c)
				if c.handler == nil {
					fmt.Printf("NIL HANDLER path=%q\n", p)
				}
			}()
		}
	}
}
EOF
go test -run TestFuzzRouterPanic -v . 2>&1 | sort | uniq -c | sort -rn | head -30; rm ./zz_fuzz_test.go

cd /echo && cat > ./zz_fuzz2_test.go <<'EOF'
package echo

import (
	"fmt"
	"math/rand"
	"net/http"
	"testing"
)

func TestFuzz2(t *testing.T) {
	segs := []string{"a", "b", ":", "*", "ab", ":", "*", "c", "a", "b"}
	rng := rand.New(rand.NewSource(7))
	seen := map[string]bool{}
	for iter := 0; iter < 20000; iter++ {
		e := New()
		r := e.router
		n := 1 + rng.Intn(5)
		for i := 0; i < n; i++ {
			np := 1 + rng.Intn(5)
			p := ""
			for j := 0; j < np; j++ {
				p += "/" + segs[rng.Intn(len(segs))]
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						key := "ADD " + p + " " + fmt.Sprint(rec)
						if !seen[key] {
							seen[key] = true
							fmt.Printf("ADD PANIC route=%q: %v\n", p, rec)
						}
					}
				}()
				r.Add(http.MethodGet, p, handlerFunc)
			}()
		}
		// random request paths
		for k := 0; k < 20; k++ {
			np := rng.Intn(5)
			p := ""
			for j := 0; j < np; j++ {
				p += "/" + segs[rng.Intn(len(segs))]
			}
			if rng.Intn(4) == 0 {
				p = p[1:]
			}
			func() {
				defer func() {
					if rec := recover(); rec != nil {
						key := "FIND " + p + " " + fmt.Sprint(rec)
						if !seen[key] {
							seen[key] = true
							fmt.Printf("FIND PANIC path=%q routes=%v: %v\n", p, r.routes, rec)
						}
					}
				}()
				c := e.NewContext(nil, nil).(*context)
				r.Find(http.MethodGet, p, c)
			}()
		}
	}
}
EOF
go test -run TestFuzz2 -v . 2>&1 | head -40; rm ./zz_fuzz2_test.go

